// Extrae el JSON del modelo sin fiarse de que venga limpio.
const salida = [];
for (const item of $input.all()) {
  const aviso = $('Validar datos').first().json;
  let bruto = item.json?.content?.[0]?.text ?? '';
  bruto = bruto.replace(/```json/gi, '').replace(/```/g, '').trim();
  let datos;
  try {
    datos = JSON.parse(bruto);
  } catch (error) {
    datos = { tipo: 'otros', urgencia: 'media', confianza: 0, razon: 'respuesta no parseable: ' + bruto.slice(0, 200) };
  }
  salida.push({
    json: {
      ...aviso,
      tipo: datos.tipo ?? 'otros',
      urgencia: datos.urgencia ?? 'media',
      producto: datos.producto ?? '',
      motivo: datos.motivo ?? '',
      confianza: Number(datos.confianza ?? 0),
      razon: datos.razon ?? '',
      estado: 'clasificada',
    },
  });
}
return salida;

